/* AudienceScout: dependency-free, local-only user interface. */
(function(){
'use strict';
const S=window.Scout, E=S.escape, $=s=>document.querySelector(s);
const paths={home:'M3 10.5 12 3l9 7.5M5 9v11h5v-6h4v6h5V9',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',layers:'m12 3 10 5-10 5L2 8l10-5ZM2 12l10 5 10-5M2 16l10 5 10-5',chart:'M4 20v-6M9 20V9M14 20V5M19 20V2',file:'M14 2H5v20h14V7l-5-5ZM14 2v6h5',laptop:'M4 3h16v14H4zM2 21h20l-2-4H4l-2 4',help:'M9.1 9a3 3 0 0 1 5.8 1c0 2-3 2-3 4M12 17h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',plus:'M12 5v14M5 12h14',arrow:'M4 12h16M14 6l6 6-6 6',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',check:'m5 12 4 4L19 6',edit:'m16 3 5 5-12 12H4v-5L16 3Z',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',search:'M21 21l-6-6M17 10A7 7 0 1 1 3 10a7 7 0 0 1 14 0',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',copy:'M8 8h13v13H8zM16 8V3H3v13h5'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const compass='<svg viewBox="0 0 40 40" aria-hidden="true"><path d="M20 2l6 12 12 6-12 6-6 12-6-12L2 20l12-6z" fill="currentColor"/><circle cx="20" cy="20" r="4" fill="white"/></svg>';
const button=(label,action,primary=false,ico='',attrs='')=>`<button class="button ${primary?'primary':''}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const link=(label,action,attrs='')=>`<button class="text-button" data-action="${action}" ${attrs}>${label}</button>`;
const fmt=n=>Number(n).toLocaleString('en-US');
let state, lastSaved=null, storageAvailable=true, corruptRaw=null, conflict=false, dirty=false;
let evidenceTab='reviews', testDraft=null, searchDraft=null, profileMode='detail', channelFilters={relevance:'',readiness:'',query:''};
let route='dashboard', tab='setup', plannerMode='survey', segment='', search='', page=1, csvPending=null, restorePending=null, modalReturnFocus=null, toastTimer;
try {lastSaved=localStorage.getItem(S.STORAGE_KEY);state=lastSaved?S.validateWorkspace(JSON.parse(lastSaved)):S.Intelligence.initialState();if(!lastSaved){lastSaved=JSON.stringify(state);localStorage.setItem(S.STORAGE_KEY,lastSaved);}}
catch(error){if(lastSaved){corruptRaw=lastSaved;state=S.Intelligence.initialState();}else{storageAvailable=false;lastSaved=null;state=S.Intelligence.initialState();}}
const project=()=>state.projects.find(p=>p.id===state.activeId)||state.projects[0];
const analysis=()=>S.analyze(project(),segment);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function commit(change,message='Saved on this device',rerender=true){
  if(corruptRaw){toast('Recover or export the unreadable workspace before making changes.');return false;}
  if(conflict){toast('This workspace changed in another window. Reload before editing.');return false;}
  const next=S.clone(state);change(next);next.updatedAt=S.now();
  const p=next.projects.find(p=>p.id===next.activeId);if(p)p.updatedAt=S.now();
  try{
    if(storageAvailable){const current=localStorage.getItem(S.STORAGE_KEY);if(current!==lastSaved){conflict=true;render();toast('Another window changed this workspace. Reload to use the latest data.');return false;}const raw=JSON.stringify(next);localStorage.setItem(S.STORAGE_KEY,raw);lastSaved=raw;}
    state=next;dirty=false;if(rerender)render();if(message)toast(storageAvailable?message:'Saved for this session only. Export a backup before closing.');return true;
  }catch(error){toast('Storage is full or unavailable. Your previous saved data is intact. Export a backup and free browser storage.');return false;}
}
function updateProject(change,message,rerender=true){return commit(s=>change(s.projects.find(p=>p.id===s.activeId)),message,rerender);}
function modal(title,body,wide=false){const d=$('#dialog');modalReturnFocus=document.activeElement;if(d.open)d.close();d.className=wide?'wide':'';d.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${E(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;d.showModal();}
function closeModal(){const d=$('#dialog');d.close();d.innerHTML='';if(modalReturnFocus&&document.contains(modalReturnFocus))modalReturnFocus.focus();}
function confirmModal(title,message,action,label='Continue',attrs=''){modal(title,`<p>${E(message)}</p><div class="dialog-footer">${button('Cancel','close-modal')}${button(label,action,true,'',attrs)}</div>`);}
function download(name,body,type='text/plain;charset=utf-8'){const blob=new Blob([body],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);toast('Export created. Check your browser’s downloads.');}
const filename=()=>project().name.replace(/[^a-zA-Z0-9_-]/g,'-').replace(/-+/g,'-').slice(0,70)||'audiencescout';
function backup(all=true){const data=all?state:{schemaVersion:S.VERSION,activeId:project().id,projects:[project()],updatedAt:S.now()};download(`AudienceScout-${all?'workspace':filename()}-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(data,null,2),'application/json');}
function navigate(dest,newTab){if(dirty){confirmModal('Leave unsaved changes?','Your form has unsaved changes. Save the form first, or discard these edits to continue.','discard-navigate','Discard edits',`data-dest="${E(dest)}" data-tab="${E(newTab||'')}"`);return;}route=dest;tab=newTab||(dest==='audience'?(S.discover(project()).ready?'profiles':'setup'):tab);page=1;if(location.hash!=='#'+dest)location.hash=dest;render();window.scrollTo(0,0);}
function header(title,description,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="button-row">${actions}</div>`:''}</div>`;}
function sampleBanner(){return project().kind==='sample'?`<div class="banner"><p><strong>Sample data.</strong> You’re exploring fictional responses. Start a real project to make it yours.</p>${link('New project','new-project')}</div>`:'';}
function empty(title,description,actions='',ico='users'){return `<div class="empty"><div class="empty-icon">${icon(ico)}</div><h2>${title}</h2><p>${description}</p><div class="button-row">${actions}</div></div>`;}
function filter(){return `<div class="filter"><label for="segment-filter">Research scope</label><select id="segment-filter"><option value="">All segments</option>${S.analyze(project()).segments.map(s=>`<option value="${E(s)}" ${segment===s?'selected':''}>${E(s)}</option>`).join('')}</select></div>`;}
function chart(a,full=false){if(!a.channels.length)return empty(a.channelAnswered?'No preferred channels reported':'No channel answers yet',a.channelAnswered?`${a.channelAnswered} respondents explicitly reported no preferred channel. There is no channel ranking to infer.`:'Add preferred channels to a response to see a ranking based on your data.',button('View responses','responses'), 'layers');return `<div class="chart" role="img" aria-label="Channel preferences from ${a.channelAnswered} respondents. ${a.channels.map(c=>E(c.name)+': '+c.count).join('; ')}">${a.channels.slice(0,full?30:6).map((c,i)=>`<div class="bar-row"><span class="bar-label">${E(c.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${c.percent}%;opacity:${Math.max(.44,1-i*.09)}"></div></div><span class="bar-value">${c.count}</span></div>`).join('')}</div><p class="chart-note">${a.channelAnswered} answered · Multiple selections allowed${a.channelMissing?` · ${a.channelMissing} missing`:''}</p>`;}
function dashboard(){return views.dashboard();}
function audience(){return views.audience();}
function field(label,name,value='',placeholder='',full=false,required=false){return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}${required?' <small>(required)</small>':''}</label><textarea id="f-${name}" name="${name}" maxlength="5000" placeholder="${E(placeholder)}" ${required?'required':''}>${E(value)}</textarea></div>`;}
function setupView(){return views.setupView();}
function plannerView(){const p=project(),guide=p.planner||S.planner(p),changed=p.planner&&p.planner.context!==S.plannerContext(p);return `<div class="toolbar"><div class="segmented" aria-label="Question format"><button class="${plannerMode==='survey'?'active':''}" data-action="planner-mode" data-mode="survey">Survey</button><button class="${plannerMode==='interview'?'active':''}" data-action="planner-mode" data-mode="interview">Interview</button></div><div class="button-row">${button('Export questions','export-planner',false,'download')}${button(p.planner?'Regenerate guide':'Save generated guide','generate-planner',true)}</div></div>${changed?'<div class="banner"><p>Your research brief changed. Regenerate the guide to use your latest inputs, or keep your edited questions.</p></div>':''}<div class="info-line">${icon('info')}<span>${p.planner?'Your saved guide is editable.':'Preview generated from your research brief. Save the guide to keep it.'} Ask neutral questions and get permission before recording. Responses are entered or imported separately.</span></div><div class="question-list">${guide[plannerMode].map((q,i)=>`<div class="question"><span class="question-num">${String(i+1).padStart(2,'0')}</span><div><span class="question-meta">${E(q.type)}</span><h3>${E(q.question)}</h3><div class="question-meta" style="margin-top:7px">Maps to ${E(S.LABELS[q.field])}</div>${q.field==='channels'?`<p class="small muted" style="margin-top:8px">Suggested choices: ${S.CHANNELS.join(', ')}, Other, None.</p>`:''}</div><button class="icon-button" data-action="edit-question" data-index="${i}" aria-label="Edit question ${i+1}">${icon('edit')}</button></div>`).join('')}</div><p class="footer-note">This is a research planning aid, not validated evidence. Adapt the wording and recruitment to your customers. For “not sure” purchase intent, leave the value blank.</p>`;}
function responsesView(){const p=project();let rows=p.responses.filter(r=>!search||[r.respondent,r.segment,r.needs,r.painPoints,r.interests,r.motivation,r.notes,...r.channels].join(' ').toLowerCase().includes(search.toLowerCase()));const total=rows.length;page=Math.min(page,Math.max(1,Math.ceil(total/10)));rows=rows.slice((page-1)*10,page*10);return `<div class="toolbar"><input type="search" id="response-search" placeholder="Search responses…" aria-label="Search responses" value="${E(search)}"><div class="button-row">${button('CSV template','csv-template',false,'download')}${button('Import CSV','import-csv',false,'upload')}${button('Add response','add-response',true,'plus')}</div></div>${!p.responses.length?empty('Let your customers do the talking.','Add a response by hand, or import a CSV from your survey tool. Review every import before saving.',button('Add your first response','add-response',true)+button('Import a CSV','import-csv')):!rows.length?empty('No matching responses','Try a different word, respondent ID, or channel.',button('Clear search','clear-search'),'search'):`<div class="table-wrap"><table><thead><tr><th>Respondent</th><th>What they need</th><th>Preferred channels</th><th>Intent</th><th>Source</th><th><span class="small">Actions</span></th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="response-link" data-action="view-response" data-id="${E(r.id)}">${E(r.respondent||'Anonymous')}</button><p>${E(r.segment||'No segment')}</p></td><td>${E(r.needs.slice(0,125)||r.painPoints.slice(0,125)||'No need answer')}${r.needs.length>125?'…':''}</td><td>${r.channels.length?r.channels.slice(0,3).map(c=>`<span class="pill">${E(c)}</span>`).join('')+(r.channels.length>3?`<span class="pill">+${r.channels.length-3}</span>`:''):'<span class="muted">Not answered</span>'}</td><td>${r.intent?`${r.intent}/5`:'—'}</td><td><span class="pill">${r.source==='sample'?'Sample':'Research'}</span><p>${E(r.method)}</p></td><td><button class="icon-button" data-action="edit-response" data-id="${E(r.id)}" aria-label="Edit ${E(r.respondent||'response')}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div><div class="pagination"><span>${(page-1)*10+1}–${Math.min(page*10,total)} of ${fmt(total)} responses</span><div class="button-row">${button('Previous','prev-page',false,'',page===1?'disabled':'')}${button('Next','next-page',false,'',page>=Math.ceil(total/10)?'disabled':'')}</div></div>`}<p class="footer-note">Use anonymous respondent IDs. Avoid storing names, emails, or other sensitive personal details unless you need them and have permission.</p>`;}
function channelsView(){return views.channelsView();}

function insightsView(){return views.insightsView();}
function markdownHTML(md){return md.split('\n').map(line=>line.startsWith('### ')?`<h3>${E(line.slice(4))}</h3>`:line.startsWith('## ')?`<h2>${E(line.slice(3))}</h2>`:line.startsWith('# ')?`<h1>${E(line.slice(2))}</h1>`:line.startsWith('- ')?`<p>• ${E(line.slice(2))}</p>`:line?`<p>${E(line)}</p>`:'').join('');}
function reportsView(){return views.reportsView();}
function render(){
  const valid=['dashboard','audience','channels','evidence','insights','reports'];if(!valid.includes(route))route='dashboard';
  const p=project();if(segment&&!p.responses.some(r=>r.segment===segment))segment='';
  document.title=`${route[0].toUpperCase()+route.slice(1)} · AudienceScout`;
  const content={dashboard,audience,channels:channelsView,evidence:()=>views.evidenceView(),insights:insightsView,reports:reportsView}[route]();
  $('#app').innerHTML=views.shell(state,route,content,{storageAvailable,conflict,searchDraft});
}
function newProjectDialog(){modal('Start an audience discovery project',`<p>Start with your offer and goals. No surveys or customer data are required. Sample projects remain separate.</p><form id="new-project-form"><label for="new-name">Project name</label><input id="new-name" name="name" required maxlength="120" placeholder="e.g. Spring product launch" autofocus><div class="dialog-footer">${button('Cancel','close-modal')}<button class="button primary" type="submit">Create project</button></div></form>`);}
function sampleDialog(){modal('Explore a sample project',`<p>These datasets contain fictional responses, created to demonstrate the workflow. They are never merged into your real research.</p><div class="project-list">${[['coffee','Everyday Coffee','24 sample responses · Coffee subscription'],['studio','Studio Flow','24 sample responses · Scheduling software']].map(([key,name,desc])=>`<div class="project-row"><div><h3>${name}</h3><p>${desc}</p></div>${button('Open sample','load-sample',false,'',`data-sample="${key}"`)}</div>`).join('')}</div>`);}
function requireResearch(){if(project().kind==='sample'){modal('Keep your research separate',`<p>This is a fictional sample project. Create a research project to add your real customer responses.</p><div class="dialog-footer">${button('Cancel','close-modal')}${button('Create research project','new-project',true)}</div>`);return false;}return true;}
function responseDialog(existing){if(!requireResearch())return;const r=existing||{channels:[],intent:null,method:'survey'};modal(existing?'Edit response':'Add a customer response',`<p>Record what a customer actually said. Leave unanswered questions blank.</p><form id="response-form" data-id="${E(r.id||'')}"><div class="form-grid"><div class="field"><label for="r-respondent">Respondent ID <small>(optional)</small></label><input id="r-respondent" name="respondent" maxlength="120" value="${E(r.respondent||'')}" placeholder="e.g. Interview 01"></div><div class="field"><label for="r-segment">Customer segment <small>(optional)</small></label><input id="r-segment" name="segment" maxlength="160" value="${E(r.segment||'')}" placeholder="e.g. First-time buyers"></div>${['needs','painPoints','interests','motivation'].map(f=>field(S.LABELS[f],f,r[f]||'','Use the respondent’s own words.')).join('')}<div class="field full"><label>Preferred channels <small>(select all mentioned)</small></label><div class="check-grid">${S.CHANNELS.map(c=>`<label class="check-option"><input type="checkbox" name="channel" value="${E(c)}" ${r.channels.includes(c)?'checked':''}>${E(c)}</label>`).join('')}</div><label for="r-custom" style="margin-top:16px">Other channels</label><input id="r-custom" name="customChannels" maxlength="500" value="${E(r.channels.filter(c=>!S.CHANNELS.includes(c)).join('; '))}" placeholder="Separate with semicolons; enter None if explicitly stated."></div><div class="field"><label for="r-intent">Purchase intent</label><select id="r-intent" name="intent"><option value="">Not answered / not sure</option>${[1,2,3,4,5].map(v=>`<option value="${v}" ${r.intent===v?'selected':''}>${v} — ${['Very unlikely','Unlikely','Neutral','Likely','Very likely'][v-1]}</option>`).join('')}</select></div><div class="field"><label for="r-method">Research method</label><select id="r-method" name="method">${['survey','interview','other'].map(m=>`<option ${r.method===m?'selected':''} value="${m}">${m[0].toUpperCase()+m.slice(1)}</option>`).join('')}</select></div><div class="field full"><label for="r-date">Response date <small>(optional)</small></label><input type="date" id="r-date" name="date" value="${E(r.date||'')}"></div>${field('Additional notes','notes',r.notes||'','Context, follow-up questions, or verbatim observations.',true)}</div><div id="response-error" class="error" role="alert"></div><div class="dialog-footer">${existing?button('Delete response','delete-response',false,'trash',`data-id="${E(r.id)}"`):''}${button('Cancel','close-modal')}<button type="submit" class="button primary">Save response</button></div></form>`,true);}
function viewResponse(id){const r=project().responses.find(x=>x.id===id);if(!r)return;modal(r.respondent||'Anonymous respondent',`<span class="pill">${r.source==='sample'?'FICTIONAL SAMPLE':'USER-PROVIDED RESEARCH'}</span><dl class="data-detail">${S.FIELDS.map(f=>`<dt>${S.LABELS[f]}</dt><dd>${E(Array.isArray(r[f])?r[f].join(', ')||'Not answered':r[f]??'Not answered')||'Not answered'}</dd>`).join('')}</dl><div class="dialog-footer">${button('Close','close-modal')}${project().kind==='research'?button('Edit response','edit-response',true,'edit',`data-id="${E(id)}"`):''}</div>`);}
function importDialog(){if(!requireResearch())return;csvPending=null;modal('Import customer responses',`<p>Choose a UTF-8 CSV or tab-separated file (up to 5 MB and 5,000 rows). You’ll map columns and review the results before saving. Your file stays on this device.</p><label for="csv-file">Response file</label><input id="csv-file" type="file" accept=".csv,.tsv,text/csv,text/tab-separated-values"><div id="import-error" class="error" role="alert"></div><div class="info-line" style="margin-top:20px">${icon('info')}<span>Use semicolons inside a channels field. Intent must be 1–5 or blank. Dates use YYYY-MM-DD. A source column labeled “sample” cannot be imported into real research.</span></div><div class="dialog-footer">${button('Download template','csv-template')}${button('Cancel','close-modal')}</div>`);}
function mappingDialog(){const c=csvPending;modal('Match your CSV columns',`<p>${c.parsed.rows.length} rows found in <strong>${E(c.name)}</strong>. Map the answers you want to use. Unmapped columns are ignored; sample source labels are always checked.</p><div class="mapping-grid">${S.FIELDS.map(f=>`<div><label for="map-${f}">${S.LABELS[f]}</label><select id="map-${f}" data-map="${f}"><option value="-1">Skip this field</option>${c.parsed.headers.map((h,i)=>`<option value="${i}" ${c.map[f]===i?'selected':''}>${E(h)}</option>`).join('')}</select></div>`).join('')}</div><div id="mapping-error" class="error" role="alert"></div><div class="dialog-footer">${button('Cancel','close-modal')}${button('Review import','preview-import',true,'arrow')}</div>`,true);}
function previewDialog(){try{csvPending.preview=S.previewImport(csvPending.parsed,csvPending.map,project());const p=csvPending.preview;modal('Review before importing',`<p>Nothing has been saved yet. Duplicate rows are skipped using the complete response content. Invalid rows are excluded.</p><div class="preview-summary"><div><strong>${p.good.length}</strong>Ready to import</div><div><strong>${p.duplicates.length}</strong>Duplicates</div><div><strong>${p.errors.length}</strong>Invalid rows</div></div>${p.errors.length?`<div class="error"><strong>Rows needing attention</strong><ul>${p.errors.slice(0,8).map(e=>`<li>Row ${e.row}: ${E(e.message)}</li>`).join('')}</ul>${p.errors.length>8?`<p>And ${p.errors.length-8} more. Download the error list for all details.</p>`:''}${link('Download error list','export-import-errors')}</div>`:''}${p.duplicates.length?`<p class="small">Skipped duplicate row numbers: ${p.duplicates.slice(0,20).join(', ')}${p.duplicates.length>20?'…':''}</p>`:''}${p.good.length?`<div class="table-wrap"><table><thead><tr><th>Respondent</th><th>Needs</th><th>Channels</th></tr></thead><tbody>${p.good.slice(0,5).map(r=>`<tr><td>${E(r.respondent||'Anonymous')}</td><td>${E(r.needs||'Not answered')}</td><td>${E(r.channels.join(', ')||'Not answered')}</td></tr>`).join('')}</tbody></table></div><p class="footer-note">Previewing the first ${Math.min(5,p.good.length)} valid rows. All ${p.good.length} valid rows will be added as user-provided research.</p>`:''}<div class="dialog-footer">${button('Back to mapping','mapping')}${button(`Import ${p.good.length} valid ${p.good.length===1?'response':'responses'}`,'commit-import',true,'',p.good.length?'':'disabled')}</div>`,true);}catch(e){$('#mapping-error').textContent=e.message;}}
function helpDialog(){modal('Your local discovery workspace',`<div class="info-line">${icon('lock')}<span>AudienceScout runs entirely in your browser. No accounts, tracking, paid APIs, or uploads.</span></div><div class="help-sections"><h3>Start with a brief, not a survey</h3><ol><li>Create a project and complete the Product brief in Audience.</li><li>Choose Analyze research brief to generate 3–5 potential customer profiles.</li><li>Compare channels and read each fit explanation and prerequisite.</li><li>Configure a validation test, start it, then record real results.</li><li>Add customer responses or reviewed observations whenever they help.</li></ol><h3>Know what is evidence</h3><p>Generated profiles and channel relevance are hypotheses. Findings distinguish user assumptions, reported observations, and source checks documented by you. Recorded tests evaluate your chosen decision rule; they do not prove a market-wide claim. Sample projects are fictional throughout.</p>${link('Read the full decision method','method')}<h3>Keep your work safe</h3><p>Projects save in this browser on this device. Keep the app at the same file path and use the same browser profile. Clearing site data, private browsing, or changing the file location may make data unavailable. Export regular JSON backups. Data is not encrypted by the app.</p><div class="button-row">${button('Back up workspace','backup-all',false,'download')}${button('Restore backup','restore')}</div><h3>Upgrade compatibility</h3><p>Version 1 and 2 projects, answers, guides, checklist records, profiles, evidence, tests and notes are preserved. Earlier projects keep their original analysis until you save the contextual research brief. Version 3 imports backups from versions 1, 2 and 3. Use the updated app for all new saves; the old app does not understand the added strategy data.</p><h3>Your projects</h3><div class="project-list">${state.projects.map(p=>`<div class="project-row"><div><h3>${E(p.name)}</h3><p>${p.kind==='sample'?'Fictional sample':'Local project'} · ${p.responses.length} optional responses</p></div><button class="icon-button" data-action="delete-project" data-id="${E(p.id)}" aria-label="Delete ${E(p.name)}">${icon('trash')}</button></div>`).join('')}</div><div class="button-row" style="margin-top:18px">${button('New project','new-project',true,'plus')}${button('Explore samples','sample')}</div><h3>Easy offline launch</h3><p>Double-click AudienceScout.html in a current browser. No server or installation is needed. Save form changes before exporting a report or backup. Reports include Markdown, HTML, print/PDF, CSV, and JSON backup formats.</p></div>`,true);}
function methodDialog(){modal('How the decision rules work',views.methodHTML(),true);}
function restoreDialog(){restorePending=null;modal('Restore a workspace backup',`<p>Select an AudienceScout JSON backup (up to 15 MB). Projects will be added as separate copies. Existing projects will remain intact.</p><label for="backup-file">Backup file</label><input id="backup-file" type="file" accept=".json,application/json"><div id="restore-error" class="error" role="alert"></div><div class="dialog-footer">${button('Cancel','close-modal')}</div>`);}
function exportHTML(){const body=markdownHTML(S.reportMarkdown(project(),segment));download(filename()+'-strategy-report.html',`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${E(project().name)} — AudienceScout strategy</title><style>body{font:14px/1.7 -apple-system,BlinkMacSystemFont,Segoe UI,sans-serif;color:#222;max-width:850px;margin:45px auto;padding:0 24px}h1{font-size:30px;line-height:1.2}h2{border-top:1px solid #ddd;padding-top:24px;margin-top:34px}h3{margin-top:24px}p{white-space:pre-wrap;overflow-wrap:anywhere}@media print{body{margin:0}h2,h3{break-after:avoid}@page{margin:18mm}}</style></head><body>${body}<p>Created with AudienceScout · Local audience discovery</p></body></html>`,'text/html;charset=utf-8');}
function profileDialog(id){
  const profile=S.discover(project()).segments.find(s=>s.id===id);if(!profile)return;
  modal('Refine this audience hypothesis',`<p>Edit the wording to reflect your context. These remain hypotheses. Channel relevance uses the structured brief and original scenario rule. Edit the brief to change product function, buyer or end-user roles.</p><form id="profile-form" data-id="${E(id)}"><div class="form-grid"><div class="field full"><label for="profile-name">Profile name</label><input id="profile-name" name="name" value="${E(profile.name)}" maxlength="120" required></div>${[['who','Who might fit'],['needs','Customer needs'],['painPoints','Potential pain points'],['motivation','Purchase motivations'],['interests','Interests to investigate'],['buyingBehavior','Possible buying behavior'],['opportunity','Marketing opportunity']].map(([key,label])=>field(label,key,profile[key],'',true)).join('')}</div><div class="error" id="profile-error" role="alert"></div><div class="dialog-footer">${button('Cancel','close-modal')}<button class="button primary" type="submit">Save profile</button></div></form>`,true);
}
function reviewDialog(existing,segmentId,channelId){
  const profiles=S.discover(project()).segments;if(!profiles.length){modal('Complete the brief first',`<p>Generate audience hypotheses before linking evidence. Existing responses remain available under Evidence.</p><div class="dialog-footer">${button('Close','close-modal')}${button('Open product brief','close-to-brief',true)}</div>`);return;}
  const channelOptions=S.Intelligence.enabled(project())?S.Intelligence.R.CHANNELS:S.CHANNEL_RULES;
  const r=existing||{segmentId:segmentId||S.activeSegment(project()).id,channelId:channelId||'',kind:channelId?'channels':'needs',stance:'mixed',sourceType:'observation'};
  modal(existing?'Review linked evidence':'Add a source-linked observation',`<p>Record a specific observation, name its source, and explain how it relates to the hypothesis. Supporting evidence does not independently verify a market claim.</p><form id="review-form" data-id="${E(r.id||'')}"><div class="form-grid"><div class="field"><label for="review-segment">Audience hypothesis</label><select id="review-segment" name="segmentId">${!profiles.some(s=>s.id===r.segmentId)?`<option value="${E(r.segmentId)}" selected>Earlier hypothesis: ${E(r.segmentId)}</option>`:""}${profiles.map(s=>`<option value="${E(s.id)}" ${r.segmentId===s.id?'selected':''}>${E(s.name)}</option>`).join('')}</select></div><div class="field"><label for="review-channel">Related channel <small>(optional)</small></label><select id="review-channel" name="channelId"><option value="">Audience only</option>${r.channelId&&!channelOptions.some(c=>c.id===r.channelId)?`<option value="${E(r.channelId)}" selected>Earlier channel: ${E(r.channelId)}</option>`:""}${channelOptions.map(c=>`<option value="${c.id}" ${r.channelId===c.id?'selected':''}>${c.name}</option>`).join('')}</select></div><div class="field"><label for="review-kind">Evidence about</label><select id="review-kind" name="kind">${[['needs','Customer needs'],['painPoints','Pain points'],['interests','Interests'],['motivation','Purchase motivation'],['channels','Channel access / fit'],['other','Other']].map(([key,label])=>`<option value="${key}" ${r.kind===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="review-stance">Your interpretation</label><select id="review-stance" name="stance">${[['mixed','Mixed / unclear'],['supports','Supports the hypothesis'],['challenges','Challenges the hypothesis']].map(([key,label])=>`<option value="${key}" ${r.stance===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="field full"><label for="review-source-choice">Evidence source</label><select id="review-source-choice" name="sourceChoice"><option value="observation">A specific observation / test result</option>${r.sourceType==='response'&&!project().responses.some(x=>x.id===r.responseId)?`<option value="response:${E(r.responseId)}" selected>Original response unavailable; choose another source</option>`:""}${project().responses.map(x=>`<option value="response:${E(x.id)}" ${r.sourceType==='response'&&r.responseId===x.id?'selected':''}>${E(x.respondent||'Anonymous')} · ${E((x.needs||x.painPoints||x.channels.join(', ')).slice(0,100))}</option>`).join('')}</select><div id="evidence-source-preview"></div></div>${evidenceCheckFields(r)}${field('Source details (required for a separate observation)','source',r.source||'','Example: a dated interview, a named test, or an observed behavior. Do not enter credentials or sensitive personal information.',true)}${field('What did you observe, and why does it support or challenge the hypothesis?','statement',r.statement||'','Be specific. Include the relevant words, behavior, or recorded result.',true,true)}<div class="field full"><label for="review-date">Observation date <small>(optional, YYYY-MM-DD)</small></label><input id="review-date" name="date" value="${E(r.date||'')}" placeholder="YYYY-MM-DD" maxlength="10"></div></div><div class="error" id="review-error" role="alert"></div><div class="dialog-footer">${existing?button('Remove review','remove-review',false,'trash',`data-id="${E(r.id)}"`):''}${button('Cancel','close-modal')}<button class="button primary" type="submit">Save evidence review</button></div></form>`,true);
  sourcePreview();
}

function evidenceCheckFields(r){return '<div class="field full"><label for="review-verification">Evidence status</label><select id="review-verification" name="verification">'+[['reported','User-reported observation (not checked)'],['assumption','User assumption'],['checked','Source-checked by me']].map(([id,label])=>'<option value="'+id+'" '+((r.verification||'reported')===id?'selected':'')+'>'+label+'</option>').join('')+'</select><p class="field-help">Only choose source-checked after inspecting the original and recording the reference, check and date below. The app does not independently verify sources.</p></div>'+field('Source reference / record identifier','reference',r.reference||'','e.g. Interview 04, dated transcript section; or source URL',true)+field('What did you check?','verificationNote',r.verificationNote||'','Describe the original material and the limits of what it establishes.',true)+'<div class="field"><label for="review-checked">Date checked</label><input type="date" id="review-checked" name="checkedAt" value="'+E(r.checkedAt||'')+'"></div>';}
function availabilityDialog(id){const c=S.Intelligence.R.CHANNELS.find(x=>x.id===id),a=S.Intelligence.availability(project(),id);if(!c)return;modal('Check channel availability','<p>Record your own dated check for '+E(c.name)+' in '+E(S.Intelligence.scope(project()))+'. Check the specific service, local access and permission needed. The app does not look up geographic coverage.</p><form id="availability-form" data-id="'+id+'"><label for="availability-status">Availability in this market</label><select id="availability-status" name="status">'+['unknown','available','unavailable'].map(x=>'<option value="'+x+'" '+(a.status===x?'selected':'')+'>'+x[0].toUpperCase()+x.slice(1)+'</option>').join('')+'</select>'+field('Source and check note','note',a.status==='unknown'?'':a.note,'Name the specific service, source or contact and what was checked.',true)+'<label for="availability-date">Date checked</label><input id="availability-date" name="date" type="date" value="'+E(a.date||'')+'"><div id="availability-error" class="error" role="alert"></div><div class="dialog-footer">'+button('Cancel','close-modal')+'<button type="submit" class="button primary">Save availability check</button></div></form>');}

function sourcePreview(){const choice=$('#review-source-choice')?.value,target=$('#evidence-source-preview');if(!target)return;const response=choice?.startsWith('response:')?project().responses.find(r=>r.id===choice.slice(9)):null;target.innerHTML=response?`<div class="source-preview"><strong>Original response · ${E(response.respondent||'Anonymous')}</strong>${['needs','painPoints','interests','motivation','notes'].filter(k=>response[k]).map(k=>`<p><span>${S.LABELS[k]}:</span> ${E(response[k])}</p>`).join('')}<p>Channels: ${E(response.channels.join(', ')||'Not answered')}</p></div>`:'';}
function channelProposal(channelId){const p=project(),s=S.activeSegment(p),c=S.matchChannels(p,s?.id).find(x=>x.id===channelId);if(!c||!c.eligible)throw Error('Resolve the channel prerequisites before configuring this test.');const b=S.brief(p);return {id:'channel-'+c.id,type:'channel',segmentId:s.id,channelId:c.id,signature:S.signature(p),title:`Test ${c.name}.`,hypothesis:`${c.name} can introduce reachable people matching ${s.name} to this offer.`,method:c.first+' Use one next step and track qualified outcomes.',metric:c.metric,denominator:'Relevant people reached or contacted',minAttempts:10,target:10,days:14,budgetCap:c.paid?(b.budget??0):0};}
function testDialog(proposal,existing=false){
  testDraft=S.clone(proposal);if(!existing){testDraft.id=S.id();testDraft.status='planned';testDraft.createdAt=S.now();testDraft.attempts=null;testDraft.successes=null;testDraft.actualSpend=null;}const locked=!!testDraft.startedAt||['running','completed'].includes(testDraft.status),readonly=locked?'readonly':'';
  modal(existing?(locked?'Record observed results':'Edit your test plan'):'Configure a validation test',`<p>${locked?'The hypothesis and decision rule were locked when the test started. Record observed values and their source.':'Set your own decision rule before starting. Suggested thresholds are planning proposals, not market benchmarks.'}</p><form id="test-form"><div class="form-grid">${field('Hypothesis','hypothesis',testDraft.hypothesis,'',true,true).replace('<textarea ',`<textarea ${readonly} `)}${field('Method','method',testDraft.method,'',true,true).replace('<textarea ',`<textarea ${readonly} `)}<div class="field"><label for="test-metric">Success metric</label><input id="test-metric" name="metric" maxlength="300" value="${E(testDraft.metric)}" required ${readonly}></div><div class="field"><label for="test-denominator">Denominator</label><input id="test-denominator" name="denominator" maxlength="300" value="${E(testDraft.denominator)}" required ${readonly}></div><div class="field"><label for="test-min">Minimum observations</label><input id="test-min" name="minAttempts" type="number" min="1" max="1000000" step="1" value="${testDraft.minAttempts}" required ${readonly}></div><div class="field"><label for="test-target">Decision threshold <small>(%)</small></label><input id="test-target" name="target" type="number" min="0" max="100" step="0.1" value="${testDraft.target}" required ${readonly}></div><div class="field"><label for="test-budget">Test spending cap <small>(USD)</small></label><input id="test-budget" name="budgetCap" type="number" min="0" max="1000000" step="0.01" value="${testDraft.budgetCap}" required ${readonly}></div><div class="field"><label for="test-days">Test duration <small>(days)</small></label><input id="test-days" name="days" type="number" min="1" max="365" step="1" value="${testDraft.days}" required ${readonly}></div>${locked?`<div class="field full"><label for="test-status">Test status</label><select id="test-status" name="status">${testDraft.status!=='completed'?'<option value="running">Still running</option>':''}<option value="completed" ${testDraft.status==='completed'?'selected':''}>Completed</option></select></div><div class="field"><label for="test-attempts">Observed denominator</label><input id="test-attempts" name="attempts" type="number" min="0" max="100000000" step="1" value="${testDraft.attempts??''}"></div><div class="field"><label for="test-successes">Observed successes</label><input id="test-successes" name="successes" type="number" min="0" max="100000000" step="1" value="${testDraft.successes??''}"></div><div class="field full"><label for="test-spend">Actual spend <small>(USD, optional)</small></label><input id="test-spend" name="actualSpend" type="number" min="0" max="1000000" step="0.01" value="${testDraft.actualSpend??''}"></div>${field('Source and result notes','resultNotes',testDraft.resultNotes||'','Where did these numbers come from? What happened? Include contradictory evidence.',true)}`:''}</div><div class="error" id="test-error" role="alert"></div><div class="dialog-footer">${button('Cancel','close-modal')}<button class="button primary" type="submit">${locked?'Save recorded results':'Save test plan'}</button></div></form>`,true);
}
document.addEventListener('click',event=>{
 const b=event.target.closest('[data-action]');if(!b)return;event.preventDefault();if(b.disabled)return;const action=b.dataset.action;
 if(dirty&&['new-project','sample','load-sample','examples','load-example','restore','confirm-restore','delete-project','confirm-delete-project'].includes(action)){toast('Save your current form before changing projects.');return;}
 if(dirty&&['availability','focus-channel','configure-test','channel-test','edit-test','start-test','review-evidence','edit-evidence','edit-profile','select-profile','profile'].includes(action)){toast('Save your current form before editing the strategy.');return;}
 switch(action){
 case 'examples':modal('Explore a research brief', '<p>Fictional examples demonstrate different purchase contexts. They contain no audience statistics.</p><div class="project-list">'+Object.entries(S.Intelligence.EXAMPLES).map(([key,x])=>'<div class="project-row"><div><h3>'+E(x.name)+'</h3><p>'+E(x.product)+'</p></div>'+button('Open example','load-example',false,'','data-example="'+key+'"')+'</div>').join('')+'</div><div class="dialog-footer">'+button('Sample survey datasets','sample')+button('Close','close-modal')+'</div>',true);break;
 case 'load-example':{const sample=S.Intelligence.example(b.dataset.example),existing=state.projects.find(x=>x.kind==='sample'&&x.name===sample.name);if(state.projects.length>=50&&!existing){toast('Maximum 50 projects.');break;}if(commit(s=>{if(existing)s.activeId=existing.id;else{s.projects.push(sample);s.activeId=sample.id;}},'Example brief opened',false)){segment='';search='';searchDraft=null;profileMode='detail';closeModal();navigate('dashboard');}break;}
 case 'compare-segments':profileMode='compare';navigate('audience','profiles');break;
 case 'profile-detail':profileMode='detail';navigate('audience','profiles');break;
 case 'focus-channel':channelFilters={relevance:'',readiness:'',query:''};if(updateProject(p=>p.discovery.compare=[b.dataset.id],'',false)){navigate('channels');$('#channel-comparison')?.scrollIntoView({behavior:'smooth',block:'start'});}break;
 case 'availability':availabilityDialog(b.dataset.id);break;
 case 'close-modal':closeModal();break;
 case 'close-to-brief':closeModal();navigate('audience','setup');break;
 case 'profiles':navigate('audience','profiles');break;
 case 'evidence':evidenceTab='reviews';navigate('evidence');break;
 case 'evidence-summary':evidenceTab='summary';navigate('evidence');break;
 case 'evidence-tab':evidenceTab=b.dataset.tab;render();break;
 case 'profile':profileMode='detail';if(updateProject(p=>p.discovery.selectedSegment=b.dataset.id,'',false))navigate('audience','profiles');break;
 case 'select-profile':updateProject(p=>p.discovery.selectedSegment=b.dataset.id,'');break;
 case 'edit-profile':profileDialog(b.dataset.id);break;
 case 'review-evidence':reviewDialog(null,b.dataset.segment,b.dataset.channel);break;
 case 'edit-evidence':reviewDialog(S.brief(project()).reviews.find(r=>r.id===b.dataset.id));break;
 case 'remove-review':confirmModal('Remove this evidence review?','The source response will remain unchanged. This removes only the interpretation and its link to a hypothesis.','confirm-remove-review','Remove review',`data-id="${E(b.dataset.id)}"`);break;
 case 'confirm-remove-review':if(updateProject(p=>p.discovery.reviews=p.discovery.reviews.filter(r=>r.id!==b.dataset.id),'Evidence review removed'))closeModal();break;
 case 'configure-test':{const proposal=S.validationPlan(project(),S.activeSegment(project())?.id).find(p=>p.type===b.dataset.type);if(proposal)testDialog(proposal);break;}
 case 'channel-test':try{testDialog(channelProposal(b.dataset.id));}catch(error){toast(error.message);}break;
 case 'channel-constraints':{const c=S.matchChannels(project(),S.activeSegment(project())?.id).find(x=>x.id===b.dataset.id);if(c)modal('Prepare this channel first',`<p>${E(c.name)} has unresolved prerequisites.</p><ul>${c.blockers.map(x=>`<li>${E(x)}</li>`).join('')}</ul><div class="dialog-footer">${button('Close','close-modal')}${button('Edit brief','close-to-brief',true)}</div>`);break;}
 case 'edit-test':{const x=S.brief(project()).experiments.find(t=>t.id===b.dataset.id);if(x)testDialog(x,true);break;}
 case 'start-test':confirmModal('Start this validation test?','Starting locks the hypothesis, method, decision threshold, duration, and spending cap. Record the actual results after running the test.','confirm-start-test','Start & lock decision rule',`data-id="${E(b.dataset.id)}"`);break;
 case 'confirm-start-test':try{const p=project(),x=S.brief(p).experiments.find(t=>t.id===b.dataset.id);if(!x)break;if(x.signature!==S.signature(p))throw Error('This draft belongs to an earlier brief. Configure a new test against your current assumptions.');if(S.brief(p).hours===0)throw Error('No time is available in the brief. Update your capacity before starting a test.');if(updateProject(p=>S.saveExperiment(p,{...x,status:'running'}),'Test started; decision rule locked'))closeModal();}catch(error){toast(error.message);}break;
 case 'remove-test':confirmModal('Remove this draft test?','Only an unstarted draft can be removed. Recorded results are preserved.','confirm-remove-test','Remove draft',`data-id="${E(b.dataset.id)}"`);break;
 case 'confirm-remove-test':if(updateProject(p=>p.discovery.experiments=p.discovery.experiments.filter(x=>x.id!==b.dataset.id||x.status!=='planned'),'Draft removed'))closeModal();break;
 case 'new-project':if(state.projects.length>=50){toast('Maximum 50 projects. Back up and remove an old project first.');break;}newProjectDialog();break;
 case 'sample':sampleDialog();break;
 case 'load-sample':{const sample=S.sampleProject(b.dataset.sample);const existing=state.projects.find(p=>p.kind==='sample'&&p.name===sample.name);if(state.projects.length>=50&&!existing){toast('Maximum 50 projects.');break;}if(commit(s=>{if(existing)s.activeId=existing.id;else{s.projects.push(sample);s.activeId=sample.id;}},'Sample project opened',false)){segment='';search='';dirty=false;closeModal();navigate('dashboard');}break;}
 case 'setup':navigate('audience','setup');break;
 case 'planner':evidenceTab='planner';navigate('evidence');break;
 case 'responses':evidenceTab='responses';navigate('evidence');break;
 case 'channels':navigate('channels');break;
 case 'insights':navigate('insights');break;
 case 'action-plan':navigate('insights');$('#action-plan')?.scrollIntoView({behavior:'smooth',block:'start'});break;
 case 'audience-tab':navigate('audience',b.dataset.tab);break;
 case 'discard-navigate':dirty=false;closeModal();navigate(b.dataset.dest,b.dataset.tab||undefined);break;
 case 'planner-mode':plannerMode=b.dataset.mode;render();break;
 case 'generate-planner':if(project().planner)confirmModal('Regenerate the research guide?','This replaces your edited questions with a fresh guide based on the current saved audience setup.','confirm-generate','Regenerate guide');else updateProject(p=>p.planner=S.planner(p),'Research guide saved');break;
 case 'confirm-generate':if(updateProject(p=>p.planner=S.planner(p),'Research guide regenerated'))closeModal();break;
 case 'edit-question':{const q=(project().planner||S.planner(project()))[plannerMode][Number(b.dataset.index)];modal('Edit research question',`<form id="question-form" data-index="${Number(b.dataset.index)}"><label for="question-text">Question</label><textarea id="question-text" name="question" maxlength="2000" required rows="5">${E(q.question)}</textarea><div class="dialog-footer">${button('Cancel','close-modal')}<button class="button primary" type="submit">Save question</button></div></form>`);break;}
 case 'export-planner':{const p=project(),g=p.planner||S.planner(p);download(filename()+'-'+plannerMode+'-guide.md',`# ${p.name} — ${plannerMode} guide\n\nTemplate-based research questions. Adapt to your context.\n\n`+g[plannerMode].map((q,i)=>`${i+1}. ${q.question}\n   Format: ${q.type}\n   Response field: ${S.LABELS[q.field]}`).join('\n\n')+'\n\nChannel options: '+S.CHANNELS.join(', ')+', Other, None.\nPurchase intent: 1 very unlikely to 5 very likely. Leave blank for not sure.');break;}
 case 'add-response':responseDialog();break;
 case 'edit-response':responseDialog(project().responses.find(r=>r.id===b.dataset.id));break;
 case 'view-response':viewResponse(b.dataset.id);break;
 case 'delete-response':confirmModal('Delete this response?','This removes the response from this project and recalculates its findings. Export a backup first if you may need it later.','confirm-delete-response','Delete response',`data-id="${E(b.dataset.id)}"`);break;
 case 'confirm-delete-response':if(updateProject(p=>p.responses=p.responses.filter(r=>r.id!==b.dataset.id),'Response deleted'))closeModal();break;
 case 'prev-page':page--;render();break;
 case 'next-page':page++;render();break;
 case 'clear-search':search='';page=1;render();break;
 case 'csv-template':download('AudienceScout-response-template.csv',S.toCSV([]),'text/csv;charset=utf-8');break;
 case 'import-csv':importDialog();break;
 case 'mapping':mappingDialog();break;
 case 'preview-import':previewDialog();break;
 case 'commit-import':{const rows=csvPending?.preview?.good;if(!rows?.length)break;if(project().responses.length+rows.length>10000){toast('A project supports up to 10,000 responses. Create another project for this import.');break;}if(updateProject(p=>p.responses.push(...rows),`${rows.length} responses imported`)){closeModal();tab='evidence';evidenceTab='responses';render();csvPending=null;}break;}
 case 'export-import-errors':download('AudienceScout-import-errors.txt',csvPending.preview.errors.map(e=>`Row ${e.row}: ${e.message}`).join('\n'));break;
 case 'help':helpDialog();break;
 case 'method':methodDialog();break;
 case 'export-report':download(filename()+'-strategy-report.md',S.reportMarkdown(project(),segment),'text/markdown;charset=utf-8');break;
 case 'export-html':exportHTML();break;
 case 'print-report':$('#print-report').innerHTML=markdownHTML(S.reportMarkdown(project(),segment));window.print();break;
 case 'export-csv':download(filename()+'-responses.csv',S.toCSV(analysis().rows),'text/csv;charset=utf-8');break;
 case 'backup-all':backup(true);break;
 case 'backup-project':backup(false);break;
 case 'restore':restoreDialog();break;
 case 'confirm-restore':{if(!restorePending)break;const copies=restorePending.projects.map(p=>({...S.clone(p),id:S.id(),name:S.text(p.name+' (restored)',120)}));if(state.projects.length+copies.length>50){toast('This would exceed 50 projects. Back up and remove older projects first.');break;}if(commit(s=>{s.projects.push(...copies);s.activeId=copies[0].id;},`${copies.length} projects restored`,false)){closeModal();segment='';search='';dirty=false;navigate('dashboard');restorePending=null;}break;}
 case 'delete-project':{const p=state.projects.find(p=>p.id===b.dataset.id);confirmModal('Delete this project?',`“${p.name}” and its ${p.responses.length} responses will be permanently removed from this browser. Back it up first if you need a copy.`,'confirm-delete-project','Delete project',`data-id="${E(p.id)}"`);break;}
 case 'confirm-delete-project':{if(commit(s=>{s.projects=s.projects.filter(p=>p.id!==b.dataset.id);if(!s.projects.length)s.projects.push(S.newProject('My research'));if(!s.projects.some(p=>p.id===s.activeId))s.activeId=s.projects[0].id;},'Project deleted',false)){closeModal();segment='';dirty=false;navigate('dashboard');}break;}
 case 'reload':window.location.reload();break;
 case 'export-corrupt':download('AudienceScout-unreadable-workspace.json',corruptRaw,'application/json');break;
 case 'reset-corrupt':confirmModal('Start a fresh workspace?','Export the unreadable data first. Starting fresh replaces the stored workspace; an exported copy is your recovery path.','confirm-reset-corrupt','Start fresh');break;
 case 'confirm-reset-corrupt':try{const fresh=S.Intelligence.initialState();const raw=JSON.stringify(fresh);localStorage.setItem(S.STORAGE_KEY,raw);state=fresh;lastSaved=raw;corruptRaw=null;closeModal();render();toast('Fresh workspace created.');}catch(e){toast('Browser storage is still unavailable. Try another browser and keep the recovery file.');}break;
 }
});
document.addEventListener('submit',event=>{
 event.preventDefault();const form=event.target,fd=new FormData(form);
 if(form.id==='research-brief-form'){
  try{const draft=S.Intelligence.applyBrief(project(),{...Object.fromEntries(fd),assets:fd.getAll('assets')});if(updateProject(p=>{p.name=draft.name;p.setup=draft.setup;p.discovery=draft.discovery;},'Research hypotheses generated',false)){searchDraft=null;profileMode='detail';navigate('dashboard');}}catch(error){$('#research-error').textContent=error.message;}return;
 }
 if(form.id==='search-brief-form'){
  if(dirty){toast('Save the research brief or notes before running another analysis.');return;}
  const query=S.text(fd.get('query'));if(!query)return;
  if(!S.Intelligence.enabled(project())||S.briefErrors(project()).length){searchDraft=query;navigate('audience','setup');return;}
  try{const p=project(),d=S.brief(p),draft=S.Intelligence.applyBrief(p,{...p.setup,...d.context,name:p.name,product:query,budget:d.budget,hours:d.hours,count:d.count,assets:d.assets,salesScope:d.salesScope,primaryGoal:d.primaryGoal});if(updateProject(p=>{p.setup=draft.setup;p.discovery=draft.discovery;},'Analysis updated from your saved context',false)){searchDraft=null;navigate('dashboard');}}catch(error){toast(error.message);}return;
 }
 if(form.id==='availability-form'){
  try{const c=project().discovery.context,record={...Object.fromEntries(fd),market:S.Intelligence.scope(project())},context=S.Intelligence.normalizeContext({...c,availability:{...c.availability,[form.dataset.id]:record}});if(updateProject(p=>p.discovery.context=context,'Availability check saved'))closeModal();}catch(error){$('#availability-error').textContent=error.message;}return;
 }
 if(form.id==='profile-form'){
   try{const values={};for(const key of S.PROFILE_FIELDS)values[key]=S.text(fd.get(key),key==='name'?120:5000);if(!values.name)throw Error('Enter a profile name.');if(updateProject(p=>p.discovery.profileEdits[form.dataset.id]=values,'Profile hypothesis saved'))closeModal();}catch(error){$('#profile-error').textContent=error.message;}
 }
 if(form.id==='review-form'){
   try{const choice=String(fd.get('sourceChoice')),raw=Object.fromEntries(fd);raw.id=form.dataset.id||S.id();raw.sourceType=choice.startsWith('response:')?'response':'observation';raw.responseId=raw.sourceType==='response'?choice.slice(9):'';if(raw.responseId){const row=project().responses.find(r=>r.id===raw.responseId);if(!row)throw Error('The selected source response is no longer available.');raw.responseFingerprint=S.fingerprint(row);}raw.hypothesisFingerprint=S.hypothesisFingerprint(project(),raw.segmentId);const review=S.validateReview(raw);if(!form.dataset.id&&S.brief(project()).reviews.length>=1000)throw Error('A project supports up to 1,000 reviews.');if(updateProject(p=>{const rows=p.discovery.reviews,index=rows.findIndex(r=>r.id===review.id);if(index<0)rows.push(review);else rows[index]=review;},'Evidence review saved'))closeModal();}catch(error){$('#review-error').textContent=error.message;}
 }
 if(form.id==='test-form'){
   try{const raw={...testDraft,...Object.fromEntries(fd)};if(updateProject(p=>S.saveExperiment(p,raw),raw.status==='planned'?'Validation plan saved':'Observed results saved'))closeModal();}catch(error){$('#test-error').textContent=error.message;}
 }
 if(form.id==='new-project-form'){const name=S.text(fd.get('name'),120);if(!name)return;const p=S.newProject(name);if(commit(s=>{s.projects.push(p);s.activeId=p.id;},'Research project created',false)){closeModal();segment='';search='';searchDraft=null;dirty=false;navigate('audience','setup');}}
 if(form.id==='setup-form'){
   try{
     const draft=S.clone(project());draft.name=S.text(fd.get('name'),120);if(!draft.name)throw Error('Enter a project name.');
     for(const key of ['product','market','characteristics','goals','assumptions'])draft.setup[key]=S.text(fd.get(key));
     const changes={};for(const key of ['customerType','offerType','salesScope','decision','primaryGoal','outcome','budget','hours','count'])changes[key]=fd.get(key);
     draft.discovery=S.normalizeDiscovery({...S.brief(draft),...changes,benefits:fd.getAll('benefits'),assets:fd.getAll('assets'),generatedAt:S.now()});
     const errors=S.briefErrors(draft);if(errors.length)throw Error(errors.join(' '));
     draft.discovery.selectedSegment=S.activeSegment(draft).id;
     if(!draft.discovery.compare.length)draft.discovery.compare=S.matchChannels(draft,draft.discovery.selectedSegment).slice(0,2).map(c=>c.id);
     if(updateProject(p=>{p.name=draft.name;p.setup=draft.setup;p.discovery=draft.discovery;},'Audience hypotheses generated',false)){tab='profiles';render();window.scrollTo(0,0);}
   }catch(error){$('#setup-error').textContent=error.message;}
 }
 if(form.id==='experiment-form')updateProject(p=>p.experimentNotes=S.text(fd.get('notes'),10000),'Experiment notes saved');
 if(form.id==='question-form'){const question=S.text(fd.get('question'),2000);if(!question)return;if(updateProject(p=>{if(!p.planner)p.planner=S.planner(p);p.planner[plannerMode][Number(form.dataset.index)].question=question;},'Question saved'))closeModal();}
 if(form.id==='response-form'){
   try{if(project().responses.length>=10000&&!form.dataset.id)throw new Error('This project has reached 10,000 responses.');const raw=Object.fromEntries(fd);raw.channels=[...fd.getAll('channel'),...S.normalizeChannels(fd.get('customChannels'))];raw.id=form.dataset.id||S.id();const r=S.response(raw);if(updateProject(p=>{const index=p.responses.findIndex(x=>x.id===r.id);if(index>=0)p.responses[index]=r;else p.responses.push(r);},form.dataset.id?'Response updated':'Response saved'))closeModal();}catch(e){$('#response-error').textContent=e.message;}
 }
});
document.addEventListener('input',event=>{
 const el=event.target;
 if(el.closest('#setup-form')||el.closest('#research-brief-form')||el.closest('#experiment-form')){dirty=true;if($('#setup-status'))$('#setup-status').textContent='Unsaved changes';}
 if(el.id==='channel-query'){channelFilters.query=el.value;const pos=el.selectionStart;render();const input=$('#channel-query');input.focus();try{input.setSelectionRange(pos,pos);}catch(e){}}
 if(el.id==='response-search'){search=el.value;page=1;const pos=el.selectionStart;render();const input=$('#response-search');input.focus();try{input.setSelectionRange(pos,pos);}catch(e){}}
});
document.addEventListener('change',async event=>{
 const el=event.target;
 if(el.id==='channel-relevance'||el.id==='channel-readiness'){channelFilters[el.id==='channel-relevance'?'relevance':'readiness']=el.value;render();}
 if(el.id==='review-source-choice')sourcePreview();
 if(el.id==='profile-select'){if(dirty){el.value=S.activeSegment(project())?.id;toast('Save your notes before changing the selected hypothesis.');return;}updateProject(p=>p.discovery.selectedSegment=el.value,'');}
 if(el.dataset.compareId){const current=S.brief(project()).compare,next=el.checked?[...new Set([...current,el.dataset.compareId])]:current.filter(x=>x!==el.dataset.compareId);if(next.length>3){el.checked=false;toast('Compare up to three channels at a time.');return;}updateProject(p=>p.discovery.compare=next,'');}
 if(el.id==='project-select'){if(dirty){el.value=state.activeId;toast('Save your current form before switching projects.');return;}if(commit(s=>s.activeId=el.value,'',false)){segment='';search='';searchDraft=null;page=1;tab=S.discover(project()).ready?'profiles':'setup';render();}}
 if(el.id==='segment-filter'){if(dirty){el.value=segment;toast('Save your experiment notes before changing the scope.');return;}segment=el.value;render();}
 if(el.dataset.actionId){const key=el.dataset.actionId,checked=el.checked;if(dirty){el.checked=!checked;toast('Save your experiment notes before changing action status.');return;}if(!updateProject(p=>p.actions[key]=checked,'Action plan updated'))el.checked=!checked;}
 if(el.dataset.map)csvPending.map[el.dataset.map]=Number(el.value);
 if(el.id==='csv-file'&&el.files[0]){
   const file=el.files[0];try{if(file.size>5*1024*1024)throw new Error('Choose a CSV smaller than 5 MB.');const raw=await file.text();const parsed=S.parseCSV(raw);csvPending={name:file.name,parsed,map:S.autoMap(parsed.headers)};mappingDialog();}catch(e){if($('#import-error'))$('#import-error').textContent=e.message;}
 }
 if(el.id==='backup-file'&&el.files[0]){
   const file=el.files[0];try{if(file.size>15*1024*1024)throw new Error('Choose a backup smaller than 15 MB.');const raw=await file.text();let data;try{data=JSON.parse(raw);}catch(e){throw new Error('This file is not valid JSON. Choose an AudienceScout backup.');}restorePending=S.validateWorkspace(data);modal('Review your backup',`<p>Found ${restorePending.projects.length} projects. These will be restored as separate copies, keeping their sample or research labels.</p><div class="project-list">${restorePending.projects.map(p=>`<div class="project-row"><div><h3>${E(p.name)}</h3><p>${p.kind==='sample'?'Fictional sample':'Research'} · ${p.responses.length} responses</p></div></div>`).join('')}</div><div class="dialog-footer">${button('Cancel','close-modal')}${button('Restore projects','confirm-restore',true)}</div>`);}catch(e){if($('#restore-error'))$('#restore-error').textContent=e.message;}
 }
});
document.addEventListener('click',event=>{const skip=event.target.closest('.skip-link');if(skip){event.preventDefault();const main=$('#main');main.setAttribute('tabindex','-1');main.focus();return;}const anchor=event.target.closest('.nav a,.brand');if(!anchor)return;event.preventDefault();navigate(anchor.getAttribute('href').slice(1));});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(next===route)return;if(dirty){history.replaceState(null,'','#'+route);navigate(next);return;}route=next;if(route==='audience')tab=S.discover(project()).ready?'profiles':'setup';render();window.scrollTo(0,0);});
window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
window.addEventListener('storage',event=>{if(event.key===S.STORAGE_KEY&&event.newValue!==lastSaved){conflict=true;render();toast('Another window changed the workspace. Reload before editing.');}});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
const viewContext={S,E,icon,button,link,header,empty,project,chart,filter,plannerView,responsesView,markdownHTML,getTab:()=>tab,getEvidenceTab:()=>evidenceTab,getEvidenceSegment:()=>segment,getSearchDraft:()=>searchDraft,getProfileMode:()=>profileMode,getChannelFilters:()=>channelFilters};
const views=window.ScoutWorkbench(viewContext,window.ScoutViews(viewContext));
route=location.hash.slice(1)||'dashboard';if(route==='audience')tab=S.discover(project()).ready?'profiles':'setup';render();
if(corruptRaw)modal('Your saved workspace needs recovery',`<p>The stored data could not be read. It has not been overwritten. Download the original data for recovery before starting fresh.</p><div class="dialog-footer">${button('Export original data','export-corrupt',true,'download')}${button('Start fresh','reset-corrupt')}</div>`);
})();
